//----------------------------------------------------------------------------
void lhpOpRegression::CreateGui()
//----------------------------------------------------------------------------
{
  if(m_Level == 0)
    CreateGuiBase();
  else if(m_BoneType == 0)
    CreateGuiPelvis();
  else if((m_BoneType - 1) /2 == 0)
    CreateGuiHumerus();
  else if((m_BoneType - 1) /2 == 1)
    CreateGuiScapula();
  else if((m_BoneType - 1) /2 == 2)
    CreateGuiClavicle();
  else if((m_BoneType - 1) /2 == 3)
    CreateGuiFemur();
}

