//----------------------------------------------------------------------------
void lhpOpRegression::OpStop(int result)
//----------------------------------------------------------------------------
{
  if (result == OP_RUN_CANCEL)
  {
    //HideGui();
    mafEventMacro(mafEvent(this,result));
  }
  else if (result == OP_RUN_OK)
  {
    //HideGui();
    mafEventMacro(mafEvent(this,result));
  }
}
//----------------------------------------------------------------------------
void lhpOpRegression::OnEvent(mafEventBase *maf_event) 
//----------------------------------------------------------------------------
{ 
  switch(maf_event->GetId())
  {
    case wxOK:          
    { 
      if(m_Level == 0)
      {
        m_Level++;
        HideGui();
        delete m_Gui;
        m_Gui = NULL;
        CreateGui();
      }
      else //if(m_Level == 1)
      {
        HideGui();
        if (Regression())
        {
          OpStop(OP_RUN_OK);
        }
        else
        {
          OpStop(OP_RUN_CANCEL);
        }
      }
      break;
    }
    case wxCANCEL:
    {    
      HideGui();
      OpStop(OP_RUN_CANCEL);
      break;
    }
    case ID_APPROX:
      break;
    default:
    {
      mafEventMacro(*maf_event); 
    }
    break;
  }
}

bool lhpOpRegression::RegressionFemur(bool right)
{
  char *namesr[] = {"RFTC", "RFME", "RFLE"};
  char *namesl[] = {"LFTC", "LFME", "LFLE"};
  char **names;
  int  inds[3];

  names = (right) ? namesr : namesl;

  for(int i = 0; i < 3; i++)
  {
    inds[i] = m_Cloud->FindLandmarkIndex(names[i]);
    if(inds[i] == -1)
    {
      char msgbuf[100];
      sprintf(msgbuf, "Landmark %s is not found", names[i]);
      wxMessageBox(msgbuf, "Error");
      return false;
    }
  }

  int FTCi = inds[0];
  int FMEi = inds[1];
  int FLEi = inds[2];

  int newIndex;
  std::vector<mafTimeStamp> kframes;

  std::vector<int> m_NewIndexes;

  if(!m_Cloud->IsOpen())
    m_Cloud->GetDataTimeStamps(kframes);
  else if(m_Cloud->GetNumberOfLandmarks() > 0)
    m_Cloud->GetLandmark(0)->GetMatrixTimeStamps(kframes);

  if(kframes.size() == 0)
    return false;

  char newLMName[100];
  int  avInd = 0;

  newLMName[0] =(right) ? 'R' : 'L';
  if(m_Inited)
  {
    if(m_Approximate[0])
    {
      sprintf(newLMName + 1, "_Head_ML");
      avInd = 0;
      while(m_Cloud->FindLandmarkIndex(newLMName) >= 0)
      {
        sprintf(newLMName + 1, "_Head_ML%d", avInd);
        avInd++;
      }
      newIndex = m_Cloud->AppendLandmark(newLMName);

      LMAdding LMdata;
      LMdata.m_Pelvic = true;
      LMdata.m_Index = newIndex;
      m_LMAdd.push_back(LMdata);

      m_NewIndexes.push_back(newIndex);
    }

    if(m_Approximate[1])
    {
      sprintf(newLMName + 1, "_Cond_Sulc_ML");
      avInd = 0;
      while(m_Cloud->FindLandmarkIndex(newLMName) >= 0)
      {
        sprintf(newLMName + 1, "_Cond_Sulc_ML%d", avInd);
        avInd++;
      }
      newIndex = m_Cloud->AppendLandmark(newLMName);

      LMAdding LMdata;
      LMdata.m_Pelvic = true;
      LMdata.m_Index = newIndex;
      m_LMAdd.push_back(LMdata);

      m_NewIndexes.push_back(newIndex);
    }

    if(m_Approximate[2])
    {
      sprintf(newLMName + 1, "_Lat_Cond_ML");
      avInd = 0;
      while(m_Cloud->FindLandmarkIndex(newLMName) >= 0)
      {
        sprintf(newLMName + 1, "_Lat_Cond_ML%d", avInd);
        avInd++;
      }
      newIndex = m_Cloud->AppendLandmark(newLMName);

      LMAdding LMdata;
      LMdata.m_Pelvic = true;
      LMdata.m_Index = newIndex;
      m_LMAdd.push_back(LMdata);

      m_NewIndexes.push_back(newIndex);
    }

    if(m_Approximate[3])
    {
      sprintf(newLMName + 1, "_Med_Cond_ML");
      avInd = 0;
      while(m_Cloud->FindLandmarkIndex(newLMName) >= 0)
      {
        sprintf(newLMName + 1, "_Med_Cond_ML%d", avInd);
        avInd++;
      }
      newIndex = m_Cloud->AppendLandmark(newLMName);

      LMAdding LMdata;
      LMdata.m_Pelvic = true;
      LMdata.m_Index = newIndex;
      m_LMAdd.push_back(LMdata);

      m_NewIndexes.push_back(newIndex);
    }
  }

  for(int nI = 0; nI < kframes.size(); nI++)
  {
    V3d<double> FTC, FME, FLE;

    m_Cloud->GetLandmark(FTCi, FTC.components, kframes[nI]);
    m_Cloud->GetLandmark(FMEi, FME.components, kframes[nI]);
    m_Cloud->GetLandmark(FLEi, FLE.components, kframes[nI]);

    int indx = 0;
    if(m_Inited)
    {
      V3d<double> V1, V2, V3, V4;
      Regr_3_Als(V1.components, V2.components, V3.components, V4.components, FTC.components, FME.components, FLE.components, right);

      if(m_Approximate[0])
        m_Cloud->SetLandmark(m_NewIndexes[indx++], V1.x, V1.y, V1.z, kframes[nI]);
      if(m_Approximate[1])
        m_Cloud->SetLandmark(m_NewIndexes[indx++], V2.x, V2.y, V2.z, kframes[nI]);
      if(m_Approximate[2])
        m_Cloud->SetLandmark(m_NewIndexes[indx++], V3.x, V3.y, V3.z, kframes[nI]);
      if(m_Approximate[3])
        m_Cloud->SetLandmark(m_NewIndexes[indx++], V4.x, V4.y, V4.z, kframes[nI]);
    }

    if(nI > 0)
      continue;

    mafMatrix mGlobal, mGlobalInv, mLocal, mLocalInv;
    m_Cloud->GetOutput()->GetAbsMatrix(mGlobal, kframes[nI]);
    mGlobalInv = mGlobal;
    mGlobalInv.Invert();
    TransformPoint(mGlobal, FTC);
    TransformPoint(mGlobal, FME);
    TransformPoint(mGlobal, FLE);
    if(!right)
    {
      FTC.x = - FTC.x;
      FME.x = - FME.x;
      FLE.x = - FLE.x;
    }
    FemurLocalFrame(FTC, FME, FLE, mLocal);
    mLocalInv = mLocal;
    mLocalInv.Invert();

    TransformPoint(mLocalInv, FTC);
    TransformPoint(mLocalInv, FME);
    TransformPoint(mLocalInv, FLE);

    double norm1 = MatrixNorm(FTC, FME, FLE);
    double norm2 = MatrixStdDev(FTC, FME, FLE);

    double sz1min, sz1max;
    double sz2min, sz2max;
    for(unsigned i = 0; i < 75; i++)
    {
      double sz1 = MatrixNorm  (V3d<double>(FemurData[i] + 478), V3d<double>(FemurData[i] + 481), V3d<double>(FemurData[i] + 484));
      double sz2 = MatrixStdDev(V3d<double>(FemurData[i] + 478), V3d<double>(FemurData[i] + 481), V3d<double>(FemurData[i] + 484));
      if(i == 0 || sz1 > sz1max)
        sz1max = sz1;
      if(i == 0 || sz1 < sz1min)
        sz1min = sz1;
      if(i == 0 || sz2 > sz2max)
        sz2max = sz2;
      if(i == 0 || sz2 < sz2min)
        sz2min = sz2;
    }
    if(norm1 < (1.0 - DeltaAllowed) * sz1min || norm1 > (1.0 + DeltaAllowed) * sz1max)
    {
      if(wxNO == wxMessageBox(wxString::Format("Source data size %lf is outside of database range (%lf, %lf). Do you want to continue?", norm1, sz1min, sz1max), "Warning.", wxYES_NO | wxCENTRE | wxICON_WARNING))
      {
        return false;
      }
    }
    std::vector<double> distances1;
    std::vector<double> distances2;

    for(unsigned i = 0; i < 75; i++)
    {
      double sz1 = MatrixNorm  (V3d<double>(FemurData[i] + 478) - FTC, 
        V3d<double>(FemurData[i] + 481) - FME, 
        V3d<double>(FemurData[i] + 484) - FLE);
      double sz2 = MatrixStdDev(V3d<double>(FemurData[i] + 478) - FTC, 
        V3d<double>(FemurData[i] + 481) - FME, 
        V3d<double>(FemurData[i] + 484) - FLE);
      distances1.push_back(sz1);
      distances2.push_back(sz2);
    }

    Mat_DP matrVec(225, 6);
    Mat_DP matrScl(75, 4);
    Vec_DP weightsVec(225);
    Vec_DP weightsScl(75);

    for(unsigned i = 0; i < 75; i++)
    {
      for(unsigned j = 0; j < 3; j++)
      {
        V3d<double> tmp(FemurData[i] + 478 + 3 * j);
        matrScl[i][j] = sqrt(tmp.length2());
        for(unsigned k = 0; k < 3; k++)
        {
          matrVec[3 * i + k][j] = FemurData[i][478 + 3 * j + k];
        }
      }
      matrScl[i][3] = 1.0;
      for(unsigned j = 0; j < 3; j++)
      {
        for(unsigned k = 0; k < 3; k++)
        {
          if(j == k)
            matrVec[3 * i + k][3 + j] = 1.0;
          else
            matrVec[3 * i + k][3 + j] = 0.0;
        }
      }
    }
    for(unsigned i = 0; i < 75; i++)
    {
      weightsVec[3 * i + 0] = 1.0 / (1.0 + distances1[i]);
      weightsVec[3 * i + 1] = 1.0 / (1.0 + distances1[i]);
      weightsVec[3 * i + 2] = 1.0 / (1.0 + distances1[i]);
      weightsScl[i]         = 1.0 / (1.0 + distances1[i]);
    }

    if(m_Approximate[4])
    {
      Vec_DP resVec(225);
      Vec_DP resScl(75);
      Vec_DP coefsVec(6);
      Vec_DP coefsScl(4);
      for(unsigned i = 0; i < 75; i++)
      {
        for(unsigned j = 0; j < 3; j++)
          resVec[3 * i + j] = FemurData[i][17 + j];
        resScl[i] = (FemurData[i][5] + FemurData[i][6] + FemurData[i][7]) / 3;
      }
      FindRegCoefs(matrVec, weightsVec, resVec, coefsVec);
      FindRegCoefs(matrScl, weightsScl, resScl, coefsScl);
      V3d<double> center;
      double radius;
      center = coefsVec[0] * FTC + coefsVec[1] * FME + coefsVec[2] * FLE + V3d<double>(coefsVec[3], coefsVec[4], coefsVec[5]);
      radius = coefsScl[0] * sqrt(FTC.length2()) + coefsScl[1] * sqrt(FME.length2()) + coefsScl[2] * sqrt(FLE.length2()) + coefsScl[3];
      TransformPoint(mLocal, center);
      if(!right)
        center.x = - center.x;
      AddSphere("Head", center.components, radius);
      TransformPoint(mGlobalInv, center);
      LMAdding LMdata;
      LMdata.m_Pelvic = false;
      LMdata.m_Name  = (right) ? "RFCH" : "LFCH";
      LMdata.m_Index = -1;
      LMdata.m_Pos = center;
      m_LMAdd.push_back(LMdata);
    }

    V3d<double> MC, LC;
    if(m_Approximate[5])
    {
      Vec_DP resVec(225);
      Vec_DP resVecO(225);
      Vec_DP resSclX(75);
      Vec_DP resSclY(75);
      Vec_DP resSclZ(75);
      Vec_DP resSclA(75);
      Vec_DP coefsVec(6);
      Vec_DP coefsVecO(6);
      Vec_DP coefsSclA(4);
      Vec_DP coefsSclX(4);
      Vec_DP coefsSclY(4);
      Vec_DP coefsSclZ(4);
      for(unsigned i = 0; i < 75; i++)
      {
        V3d<double> x;
        V3d<double> y;
        V3d<double> z;
        for(unsigned j = 0; j < 3; j++)
        {
          resVec[3 * i + j] = FemurData[i][276 + j];
          x[j] = FemurData[i][267 + j];
          y[j] = FemurData[i][270 + j];
          z[j] = FemurData[i][273 + j];
        }
        mafMatrix mtr;
        V3d<double> ha, p;
        double a, t;
        x /= sqrt(x.length2());
        y /= sqrt(y.length2());
        z /= sqrt(z.length2());
        mtr.SetElement(0, 0, x[0]);
        mtr.SetElement(1, 0, x[1]);
        mtr.SetElement(2, 0, x[2]);

        mtr.SetElement(0, 1, y[0]);
        mtr.SetElement(1, 1, y[1]);
        mtr.SetElement(2, 1, y[2]);

        mtr.SetElement(0, 2, z[0]);
        mtr.SetElement(1, 2, z[1]);
        mtr.SetElement(2, 2, z[2]);
        MatrixToHelicalAxis(mtr, ha.components, p.components, a, t);
        for(unsigned j = 0; j < 3; j++)
        {
          resVecO[3 * i + j] = ha[j];
        }

        resSclA[i] = a;
        resSclX[i] = FemurData[i][264];
        resSclY[i] = FemurData[i][265];
        resSclZ[i] = FemurData[i][266];
      }
      FindRegCoefs(matrVec, weightsVec, resVec, coefsVec);
      FindRegCoefs(matrVec, weightsVec, resVecO, coefsVecO);
      FindRegCoefs(matrScl, weightsScl, resSclA, coefsSclA);
      FindRegCoefs(matrScl, weightsScl, resSclX, coefsSclX);
      FindRegCoefs(matrScl, weightsScl, resSclY, coefsSclY);
      FindRegCoefs(matrScl, weightsScl, resSclZ, coefsSclZ);
      V3d<double> center;
      V3d<double> ori;
      double radius[3], angle;
      center = coefsVec[0] * FTC + coefsVec[1] * FME + coefsVec[2] * FLE + V3d<double>(coefsVec[3], coefsVec[4], coefsVec[5]);
      ori    = coefsVecO[0] * FTC + coefsVecO[1] * FME + coefsVecO[2] * FLE + V3d<double>(coefsVecO[3], coefsVecO[4], coefsVecO[5]);
      angle  = coefsSclA[0] * sqrt(FTC.length2()) + coefsSclA[1] * sqrt(FME.length2()) + coefsSclA[2] * sqrt(FLE.length2()) + coefsSclA[3];
      radius[0] = coefsSclX[0] * sqrt(FTC.length2()) + coefsSclX[1] * sqrt(FME.length2()) + coefsSclX[2] * sqrt(FLE.length2()) + coefsSclX[3];
      radius[1] = coefsSclY[0] * sqrt(FTC.length2()) + coefsSclY[1] * sqrt(FME.length2()) + coefsSclY[2] * sqrt(FLE.length2()) + coefsSclY[3];
      radius[2] = coefsSclZ[0] * sqrt(FTC.length2()) + coefsSclZ[1] * sqrt(FME.length2()) + coefsSclZ[2] * sqrt(FLE.length2()) + coefsSclZ[3];
      mafMatrix mFin;
      mafTransform *mT = NULL;
      ori /= sqrt(ori.length2());
      TransformPoint(mLocal, center);
      TransformVector(mLocal, ori);
      if(!right)
      {
        ori.x = -ori.x;
        center.x = -center.x;
      }
      mT->HelicalAxisToMatrix(ori.components, angle, mFin);
      mFin.SetElement(0, 3, center[0]);
      mFin.SetElement(1, 3, center[1]);
      mFin.SetElement(2, 3, center[2]);
      AddEllipsoid("Lat_Cond", mFin, radius);
      TransformPoint(mGlobalInv, center);
      LMAdding LMdata;
      LMdata.m_Pelvic = false;
      LMdata.m_Name  = (right) ? "RFLC" : "LFLC";
      LMdata.m_Index = -1;
      LMdata.m_Pos = center;
      m_LMAdd.push_back(LMdata);
      LC = center;
    }

    if(m_Approximate[6])
    {
      Vec_DP resVec(225);
      Vec_DP resVecO(225);
      Vec_DP resSclX(75);
      Vec_DP resSclY(75);
      Vec_DP resSclZ(75);
      Vec_DP resSclA(75);
      Vec_DP coefsVec(6);
      Vec_DP coefsVecO(6);
      Vec_DP coefsSclA(4);
      Vec_DP coefsSclX(4);
      Vec_DP coefsSclY(4);
      Vec_DP coefsSclZ(4);
      for(unsigned i = 0; i < 75; i++)
      {
        V3d<double> x;
        V3d<double> y;
        V3d<double> z;
        for(unsigned j = 0; j < 3; j++)
        {
          resVec[3 * i + j] = FemurData[i][313 + j];
          x[j] = FemurData[i][304 + j];
          y[j] = FemurData[i][307 + j];
          z[j] = FemurData[i][310 + j];
        }
        mafMatrix mtr;
        V3d<double> ha, p;
        double a, t;
        x /= sqrt(x.length2());
        y /= sqrt(y.length2());
        z /= sqrt(z.length2());
        mtr.SetElement(0, 0, x[0]);
        mtr.SetElement(1, 0, x[1]);
        mtr.SetElement(2, 0, x[2]);

        mtr.SetElement(0, 1, y[0]);
        mtr.SetElement(1, 1, y[1]);
        mtr.SetElement(2, 1, y[2]);

        mtr.SetElement(0, 2, z[0]);
        mtr.SetElement(1, 2, z[1]);
        mtr.SetElement(2, 2, z[2]);
        MatrixToHelicalAxis(mtr, ha.components, p.components, a, t);
        for(unsigned j = 0; j < 3; j++)
        {
          resVecO[3 * i + j] = ha[j];
        }

        resSclA[i] = a;
        resSclX[i] = FemurData[i][301];
        resSclY[i] = FemurData[i][302];
        resSclZ[i] = FemurData[i][303];
      }

      FindRegCoefs(matrVec, weightsVec, resVec, coefsVec);
      FindRegCoefs(matrVec, weightsVec, resVecO, coefsVecO);
      FindRegCoefs(matrScl, weightsScl, resSclA, coefsSclA);
      FindRegCoefs(matrScl, weightsScl, resSclX, coefsSclX);
      FindRegCoefs(matrScl, weightsScl, resSclY, coefsSclY);
      FindRegCoefs(matrScl, weightsScl, resSclZ, coefsSclZ);
      V3d<double> center;
      V3d<double> ori;
      double radius[3], angle;
      center = coefsVec[0] * FTC + coefsVec[1] * FME + coefsVec[2] * FLE + V3d<double>(coefsVec[3], coefsVec[4], coefsVec[5]);
      ori    = coefsVecO[0] * FTC + coefsVecO[1] * FME + coefsVecO[2] * FLE + V3d<double>(coefsVecO[3], coefsVecO[4], coefsVecO[5]);
      angle  = coefsSclA[0] * sqrt(FTC.length2()) + coefsSclA[1] * sqrt(FME.length2()) + coefsSclA[2] * sqrt(FLE.length2()) + coefsSclA[3];
      radius[0] = coefsSclX[0] * sqrt(FTC.length2()) + coefsSclX[1] * sqrt(FME.length2()) + coefsSclX[2] * sqrt(FLE.length2()) + coefsSclX[3];
      radius[1] = coefsSclY[0] * sqrt(FTC.length2()) + coefsSclY[1] * sqrt(FME.length2()) + coefsSclY[2] * sqrt(FLE.length2()) + coefsSclY[3];
      radius[2] = coefsSclZ[0] * sqrt(FTC.length2()) + coefsSclZ[1] * sqrt(FME.length2()) + coefsSclZ[2] * sqrt(FLE.length2()) + coefsSclZ[3];
      mafMatrix mFin;
      mafTransform *mT = NULL;
      ori /= sqrt(ori.length2());
      TransformPoint(mLocal, center);
      TransformVector(mLocal, ori);
      if(!right)
      {
        ori.x = -ori.x;
        center.x = -center.x;
      }
      mT->HelicalAxisToMatrix(ori.components, angle, mFin);
      mFin.SetElement(0, 3, center[0]);
      mFin.SetElement(1, 3, center[1]);
      mFin.SetElement(2, 3, center[2]);
      AddEllipsoid("Med_Cond", mFin, radius);
      TransformPoint(mGlobalInv, center);
      LMAdding LMdata;
      LMdata.m_Pelvic = false;
      LMdata.m_Name  = (right) ? "RFMC" : "LFMC";
      LMdata.m_Index = -1;
      LMdata.m_Pos = center;
      m_LMAdd.push_back(LMdata);
      MC = center;
    }
    if(m_Approximate[5] && m_Approximate[6])
    {
      LMAdding LMdata;
      LMdata.m_Pelvic = false;
      LMdata.m_Name  = (right) ? "RFBC" : "LFBC";
      LMdata.m_Index = -1;
      LMdata.m_Pos = (LC + MC) / 2;
      m_LMAdd.push_back(LMdata);
    }
    if(m_Approximate[7])
    {
      Vec_DP resVec1(225);
      Vec_DP resVec2(225);
      Vec_DP coefsVec1(6);
      Vec_DP coefsVec2(6);
      for(unsigned i = 0; i < 75; i++)
      {
        for(unsigned j = 0; j < 3; j++)
        {
          resVec1[3 * i + j] = FemurData[i][419 + j];
          resVec2[3 * i + j] = FemurData[i][422 + j];
        }
      }
      FindRegCoefs(matrVec, weightsVec, resVec1, coefsVec1);
      FindRegCoefs(matrVec, weightsVec, resVec2, coefsVec2);
      V3d<double> center;
      V3d<double> normal;
      center = coefsVec1[0] * FTC + coefsVec1[1] * FME + coefsVec1[2] * FLE + V3d<double>(coefsVec1[3], coefsVec1[4], coefsVec1[5]);
      normal = coefsVec2[0] * FTC + coefsVec2[1] * FME + coefsVec2[2] * FLE + V3d<double>(coefsVec2[3], coefsVec2[4], coefsVec2[5]);
      TransformPoint(mLocal, center);
      TransformVector(mLocal, normal);
      if(!right)
      {
        center.x = - center.x;
        normal.x = - normal.x;
      }
      AddPlane("Lat_Patella", center.components, normal.components);
      AddArrow("Lat_Patella", center.components, normal.components);
      TransformPoint(mGlobalInv, center);
      LMAdding LMdata;
      LMdata.m_Pelvic = false;
      //LMdata.m_Name  = "Groove";
      LMdata.m_Name  = (right) ? "RFLP" : "LFLP";
      LMdata.m_Index = -1;
      LMdata.m_Pos = center;
      m_LMAdd.push_back(LMdata);
    }
    if(m_Approximate[8])
    {
      Vec_DP resVec1(225);
      Vec_DP resVec2(225);
      Vec_DP coefsVec1(6);
      Vec_DP coefsVec2(6);
      for(unsigned i = 0; i < 75; i++)
      {
        for(unsigned j = 0; j < 3; j++)
        {
          resVec1[3 * i + j] = FemurData[i][411 + j];
          resVec2[3 * i + j] = FemurData[i][414 + j];
        }
      }
      FindRegCoefs(matrVec, weightsVec, resVec1, coefsVec1);
      FindRegCoefs(matrVec, weightsVec, resVec2, coefsVec2);
      V3d<double> center;
      V3d<double> normal;
      center = coefsVec1[0] * FTC + coefsVec1[1] * FME + coefsVec1[2] * FLE + V3d<double>(coefsVec1[3], coefsVec1[4], coefsVec1[5]);
      normal = coefsVec2[0] * FTC + coefsVec2[1] * FME + coefsVec2[2] * FLE + V3d<double>(coefsVec2[3], coefsVec2[4], coefsVec2[5]);
      TransformPoint(mLocal, center);
      TransformVector(mLocal, normal);
      if(!right)
      {
        center.x = - center.x;
        normal.x = - normal.x;
      }
      AddPlane("Med_Patella", center.components, normal.components);
      AddArrow("Med_Patella", center.components, normal.components);
      TransformPoint(mGlobalInv, center);
      LMAdding LMdata;
      LMdata.m_Pelvic = false;
      //LMdata.m_Name  = "Groove";
      LMdata.m_Name  = (right) ? "RFMP" : "LFMP";
      LMdata.m_Index = -1;
      LMdata.m_Pos = center;
      m_LMAdd.push_back(LMdata);
    }
    if(m_Approximate[9])
    {
      Vec_DP resVec1(225);
      Vec_DP resVec2(225);
      Vec_DP coefsVec1(6);
      Vec_DP coefsVec2(6);
      for(unsigned i = 0; i < 75; i++)
      {
        for(unsigned j = 0; j < 3; j++)
        {
          resVec1[3 * i + j] = FemurData[i][427 + j];
          resVec2[3 * i + j] = FemurData[i][430 + j];
        }
      }
      FindRegCoefs(matrVec, weightsVec, resVec1, coefsVec1);
      FindRegCoefs(matrVec, weightsVec, resVec2, coefsVec2);
      V3d<double> center;
      V3d<double> normal;
      center = coefsVec1[0] * FTC + coefsVec1[1] * FME + coefsVec1[2] * FLE + V3d<double>(coefsVec1[3], coefsVec1[4], coefsVec1[5]);
      normal = coefsVec2[0] * FTC + coefsVec2[1] * FME + coefsVec2[2] * FLE + V3d<double>(coefsVec2[3], coefsVec2[4], coefsVec2[5]);
      TransformPoint(mLocal, center);
      TransformVector(mLocal, normal);
      if(!right)
      {
        center.x = - center.x;
        normal.x = - normal.x;
      }
      AddPlane("Sulcus", center.components, normal.components);
      AddArrow("Sulcus", center.components, normal.components);
      TransformPoint(mGlobalInv, center);
      LMAdding LMdata;
      LMdata.m_Pelvic = false;
      //LMdata.m_Name  = "Groove";
      LMdata.m_Name  = (right) ? "RFSC" : "LFSC";
      LMdata.m_Index = -1;
      LMdata.m_Pos = center;
      m_LMAdd.push_back(LMdata);
    }
   }
  return true;
}

