    double sz1 = MatrixNorm  (V3d<double>(ScapulaData[i] + 3 * usedALs[0]) - AL1, 
      V3d<double>(ScapulaData[i] + 3 * usedALs[1]) - AL2, 
      V3d<double>(ScapulaData[i] + 3 * usedALs[2]) - AL4);
