    Vec_DP coefsScl(4);
    for(unsigned i = 0; i < 57; i++)
    {
      for(unsigned j = 0; j < 3; j++)
        resVec[3 * i + j] = ScapulaData[i][30 + j];
      resScl[i] = ScapulaData[i][33];
    }
    FindRegCoefs(matrVec, weightsVec, resVec, coefsVec);
    FindRegCoefs(matrScl, weightsScl, resScl, coefsScl);
    V3d<double> center;
