void lhpOpRegression::AddPlane(const mafString& name, double *center, double *normal)
{
  mafVMESurfaceRegParam *srf = NULL;
  mafMatrix mtr;
  mtr.Identity();
  mafNEW(srf);
  srf->SetName(name);
  srf->ReparentTo(m_Input->GetParent());
  srf->SetGeometryType(mafVMESurfaceRegParam::PARAMETRIC_PLANE);
  srf->SetPlaneNormal(normal);
  srf->SetPlaneCenter(center);
  srf->SetAbsMatrix(mtr);
  m_Added.push_back(srf);
}

void lhpOpRegression::AddArrow(const mafString& name, double *center, double *normal)
{
  mafVMEArrow *srf = NULL;
  mafMatrix mtr;
  mtr.Identity();
  mafNEW(srf);
  srf->SetName(name);
  srf->ReparentTo(m_Input->GetParent());

  V3d<double> norm(normal);
  V3d<double> dir1(1.0, 1.0, 1.0);
  V3d<double> dir2;
  double mx = fabs(norm[0]);
  int mxi   = 0;
  if(fabs(norm[1]) > mx)
  {
    mx = fabs(norm[1]);
    mxi = 1;
  }
  if(fabs(norm[2]) > mx)
  {
    mx = fabs(norm[2]);
    mxi = 2;
  }
  double dot = norm * dir1;
  dir1[mxi] -= dot / norm[mxi];
  dir2 = norm ^ dir1;
  dir1 /= sqrt(dir1.length2());
  dir2 /= sqrt(dir2.length2());
  norm /= sqrt(norm.length2());
  V3d<double> origin(center);
  for(int i = 0; i < 3; i++)
    mtr.SetElement(i, 3, origin[i]);
  mtr.SetElement(3, 3, 1.0);

  for(int i = 0; i < 3; i++)
    mtr.SetElement(i, 0, dir1[i]);
  mtr.SetElement(3, 0, 0.0);

  for(int i = 0; i < 3; i++)
    mtr.SetElement(i, 1, dir2[i]);
  mtr.SetElement(3, 1, 0.0);

  for(int i = 0; i < 3; i++)
    mtr.SetElement(i, 2, norm[i]);
  mtr.SetElement(3, 2, 0.0);
  mtr.SetTimeStamp(-1);
  srf->SetAbsMatrix(mtr);
  srf->SetScaleFactor(10.0);
  m_Added.push_back(srf);
}

//----------------------------------------------------------------------------
void lhpOpRegression::OpDo()
//----------------------------------------------------------------------------
{
  for(unsigned i = 0; i < m_Added.size(); i++)
    mafEventMacro(mafEvent(this, VME_ADD, m_Added[i]));
  for(unsigned i = 0; i < m_LMAdd.size(); i++)
  {
    if(!m_LMAdd[i].m_Pelvic)
    {
      m_LMAdd[i].m_Index = m_Cloud->AppendLandmark(m_LMAdd[i].m_Name);
      if(m_LMAdd[i].m_Index != -1)
      {
        m_Cloud->SetLandmark(m_LMAdd[i].m_Index, m_LMAdd[i].m_Pos.x, m_LMAdd[i].m_Pos.y, m_LMAdd[i].m_Pos.z);
      }
    }
  }
  return;
}



//----------------------------------------------------------------------------
void lhpOpRegression::OpUndo()
//----------------------------------------------------------------------------
{
  for(unsigned i = 0; i < m_Added.size(); i++)
    mafEventMacro(mafEvent(this, VME_REMOVE, m_Added[i]));
  for(unsigned i = m_LMAdd.size(); i > 0; i--)
  {
    if(m_LMAdd[i - 1].m_Index != -1)
    {
      m_Cloud->RemoveLandmark(m_LMAdd[i].m_Index);
    }
  }
}

bool lhpOpRegression::Config(LibHandle handle)
{
  if((Regr_4_Als=(bool(*)(double glob[], double loc[], double rad[], double transf[], double p1[], double p2[], double p3[], double p4[], bool pelvic, bool left))mafDynamicLoader::GetSymbolAddress(handle, "Regr_4_Als")) &&
     (Regr_3_Als=(bool(*)(double V1[], double V2[], double V3[], double V4[], double FTC[], double FME[], double FLE[], bool left))mafDynamicLoader::GetSymbolAddress(handle, "Regr_3_Als")))
  {
    m_Inited = true;
    return true;
  }
  m_Inited = false;
  return false;
}

